document.querySelectorAll(".animate-wrap").forEach((e=>{const t=e.querySelector(".animate-card"),a=e.querySelector(".animate-bg");let r,n=e.offsetWidth,o=e.offsetHeight;e.addEventListener("mousemove",(r=>{const s=e.getBoundingClientRect(),l=r.clientX-s.left-n/2,d=r.clientY-s.top-o/2,i=l/n,m=d/o,c=30*i,f=-30*m,u=-40*i,g=-40*m;t.style.transform=`rotateY(${c}deg) rotateX(${f}deg)`,a.style.transform=`translateX(${u}px) translateY(${g}px)`})),e.addEventListener("mouseleave",(()=>{r=setTimeout((()=>{t.style.transform="rotateY(0deg) rotateX(0deg)",a.style.transform="translateX(0px) translateY(0px)"}),1e3)})),e.addEventListener("mouseenter",(()=>{clearTimeout(r)}))}));